/* Generated by Archon. Build separately: cc -std=c99 -O2 RunSandbox.c -o RunSandbox
 *
 * Linux x86-64 (kernel 6.3+), native static freestanding ET_EXEC with load
 * segments below 4 GiB and write/exit only. Requires Landlock, seccomp,
 * executable memfds and /proc/self/fd.
 * The caller supplies a local, readable, executable file. No library loader,
 * no stdin, no inherited environment or child descriptors beyond a private
 * output pipe. Raw child output is untrusted. The wall timeout covers the
 * child, not setup in the parent or relaying output after the child is reaped.
 * This is not a VM, a kernel/side-channel isolation boundary, or an
 * environment for arbitrary Linux executables. Host core-dump services,
 * kernel logging, and hostile local users are not isolated. Run as a normal
 * user; do not install setuid.
 */
#ifndef _GNU_SOURCE
#define _GNU_SOURCE
#endif
#include <stdio.h>
#include <string.h>

enum { WALL_TIMEOUT = 124, OUTPUT_EXCEEDED = 125, LAUNCHER_FAILED = 126 };

static void usage(FILE *stream)
{
    fputs("usage: RunSandbox [--timeout-ms N] [--] PROGRAM [ARG ...]\n"
          "  Linux x86-64 static freestanding ELF (no loader or libc startup).\n"
          "  Child stdout and stderr share stdout; launcher status goes to stderr.\n"
          "  Wall timeout: 2000 ms by default, 1..30000 ms allowed.\n"
          "  Returns the child exit code, or 1 for child signals or reserved child codes.\n"
          "  Reserved: 124 wall timeout, 125 output limit (64 KiB), 126 launcher failure.\n", stream);
}

