/* MFD_EXEC was added in Linux 6.3. An older/disallowing kernel must fail. */
#ifndef MFD_EXEC
#define MFD_EXEC 0x0010U
#endif

#define IMAGE_LIMIT (16u * 1024u * 1024u)
#define OUTPUT_LIMIT (64u * 1024u)
#define IMAGE_FD 3
#define ERROR_FD 4
#define PAGE_BYTES 4096u
/* Only the launcher has a read-only zero page here. All validated PT_LOAD
 * segments end below it. ET_EXEC has no relocation or interpreter, the
 * native x86-64 initial stack/vDSO are far above it, and no memory-management
 * syscalls are allowed. Binding execveat to this pointer prevents pathname
 * exec (an absolute path would otherwise ignore the dirfd argument). */
#define EMPTY_ADDRESS UINT64_C(0x100000000)

static volatile sig_atomic_t interrupted;

static void interruption(int number)
{
    interrupted = number;
}

static int set_handler(int number, void (*handler)(int))
{
    struct sigaction action = {0};
    action.sa_handler = handler;
    if (sigemptyset(&action.sa_mask) < 0)
        return -1;
    return sigaction(number, &action, NULL);
}

static int parse_timeout(const char *text)
{
    int number = 0;
    for (; *text; ++text) {
        if (*text < '0' || *text > '9' || number > 3000)
            return -1;
        number = number * 10 + (*text - '0');
    }
    return number >= 1 && number <= 30000 ? number : -1;
}

static int close_above(unsigned int first)
{
    return syscall(SYS_close_range, first, UINT_MAX, 0U) == 0 ? 0 : -1;
}

static int preserve_stdio_slots(void)
{
    int fd;
    for (fd = 0; fd < 3; ++fd) {
        int slot;
        if (fcntl(fd, F_GETFD) >= 0)
            continue;
        if (errno != EBADF)
            return -1;
        slot = open("/dev/null", O_RDWR | O_CLOEXEC);
        if (slot < 0)
            return -1;
        if (slot != fd) {
            close(slot);
            errno = EIO;
            return -1;
        }
    }
    return 0;
}

static int write_all(int fd, const void *buffer, size_t size)
{
    const unsigned char *bytes = buffer;
    while (size != 0) {
        ssize_t n = write(fd, bytes, size);
        if (n < 0 && errno == EINTR)
            continue;
        if (n <= 0)
            return -1;
        bytes += (size_t)n;
        size -= (size_t)n;
    }
    return 0;
}

static int read_exact(int fd, void *buffer, size_t size, off_t offset)
{
    unsigned char *bytes = buffer;
    while (size != 0) {
        ssize_t n = pread(fd, bytes, size, offset);
        if (n < 0 && errno == EINTR)
            continue;
        if (n <= 0) {
            if (n == 0)
                errno = ENOEXEC;
            return -1;
        }
        bytes += (size_t)n;
        size -= (size_t)n;
        offset += n;
    }
    return 0;
}

static int validate_elf(int fd, uint64_t size)
{
    Elf64_Ehdr elf;
    unsigned int i;
    int has_entry = 0;
    if (size < sizeof(elf) || read_exact(fd, &elf, sizeof(elf), 0) < 0)
        return 0;
    if (memcmp(elf.e_ident, ELFMAG, SELFMAG) != 0 ||
        elf.e_ident[EI_CLASS] != ELFCLASS64 || elf.e_ident[EI_DATA] != ELFDATA2LSB ||
        elf.e_ident[EI_VERSION] != EV_CURRENT || elf.e_version != EV_CURRENT ||
        (elf.e_ident[EI_OSABI] != ELFOSABI_SYSV && elf.e_ident[EI_OSABI] != ELFOSABI_LINUX) ||
        elf.e_type != ET_EXEC || elf.e_machine != EM_X86_64 || elf.e_flags != 0 ||
        elf.e_ehsize != sizeof(elf) || elf.e_phentsize != sizeof(Elf64_Phdr) ||
        elf.e_phnum == 0 || elf.e_phnum > 64 || elf.e_phoff < sizeof(elf) ||
        elf.e_phoff > size || size - elf.e_phoff < elf.e_phnum * sizeof(Elf64_Phdr))
        return 0;
    for (i = 0; i < elf.e_phnum; ++i) {
        Elf64_Phdr ph;
        off_t offset = (off_t)(elf.e_phoff + i * sizeof(ph));
        if (read_exact(fd, &ph, sizeof(ph), offset) < 0 ||
            ph.p_type == PT_INTERP || ph.p_type == PT_DYNAMIC || ph.p_type == PT_SHLIB ||
            (ph.p_type == PT_GNU_STACK && (ph.p_flags & PF_X)))
            return 0;
        if (ph.p_type != PT_LOAD)
            continue;
        if ((ph.p_flags & (PF_W | PF_X)) == (PF_W | PF_X) ||
            ph.p_offset > size || ph.p_filesz > size - ph.p_offset ||
            ph.p_filesz > ph.p_memsz || ph.p_vaddr < PAGE_BYTES ||
            ph.p_vaddr >= EMPTY_ADDRESS || ph.p_memsz > EMPTY_ADDRESS - ph.p_vaddr ||
            ph.p_offset % PAGE_BYTES != ph.p_vaddr % PAGE_BYTES)
            return 0;
        if ((ph.p_flags & PF_X) && elf.e_entry >= ph.p_vaddr &&
            elf.e_entry - ph.p_vaddr < ph.p_filesz)
            has_entry = 1;
    }
    return has_entry;
}

/* Pin the regular source before opening it for reading. Consume a sealed
 * anonymous snapshot, so both validation and exec see exactly the same bytes.
 * The original executable must pass the effective-ID execute/noexec check. */
static const char *load_image(const char *path, int *image_out)
{
    int pinned = -1, input = -1, image = -1, saved_errno;
    struct stat original, reopened;
    char link[64];
    unsigned char buf[4096];
    off_t offset;
    const char *failure = "open program";
    pinned = open(path, O_PATH | O_NOFOLLOW | O_CLOEXEC);
    if (pinned < 0 || fstat(pinned, &original) < 0)
        goto done;
    failure = "program must be a regular executable file (no symlinks or set-ID)";
    if (!S_ISREG(original.st_mode) || (original.st_mode & (S_ISUID | S_ISGID)) ||
        !(original.st_mode & (S_IXUSR | S_IXGRP | S_IXOTH))) {
        errno = EACCES;
        goto done;
    }
    if (syscall(SYS_faccessat2, pinned, "", X_OK, AT_EMPTY_PATH | AT_EACCESS) < 0)
        goto done;
    failure = "program size is outside the supported ELF range";
    if (original.st_size <= 0 || original.st_size > IMAGE_LIMIT) {
        errno = ENOEXEC;
        goto done;
    }
    failure = "reopen pinned program (requires /proc/self/fd)";
    (void)snprintf(link, sizeof(link), "/proc/self/fd/%d", pinned);
    input = open(link, O_RDONLY | O_CLOEXEC | O_NONBLOCK);
    if (input < 0 || fstat(input, &reopened) < 0)
        goto done;
    if (!S_ISREG(reopened.st_mode) || reopened.st_ino != original.st_ino ||
        reopened.st_dev != original.st_dev) {
        errno = EACCES;
        goto done;
    }
    failure = "create executable memfd (requires Linux 6.3+ and executable memfds)";
    image = (int)syscall(SYS_memfd_create, "archon-program", MFD_CLOEXEC | MFD_ALLOW_SEALING | MFD_EXEC);
    if (image < 0)
        goto done;
    failure = "read program snapshot";
    for (offset = 0; offset < original.st_size;) {
        off_t remaining = original.st_size - offset;
        size_t count = remaining < (off_t)sizeof(buf) ? (size_t)remaining : sizeof(buf);
        if (read_exact(input, buf, count, offset) < 0 || write_all(image, buf, count) < 0)
            goto done;
        offset += (off_t)count;
    }
    failure = "seal program snapshot";
    if (fchmod(image, S_IRUSR | S_IXUSR) < 0 ||
        fcntl(image, F_ADD_SEALS, F_SEAL_WRITE | F_SEAL_GROW | F_SEAL_SHRINK | F_SEAL_SEAL) < 0)
        goto done;
    failure = "unsupported executable; expected a static non-PIE x86-64 ELF";
    if (!validate_elf(image, (uint64_t)original.st_size)) {
        errno = ENOEXEC;
        goto done;
    }
    failure = NULL;
    *image_out = image;
done:
    saved_errno = errno;
    if (input >= 0)
        close(input);
    if (pinned >= 0)
        close(pinned);
    if (image >= 0 && failure)
        close(image);
    errno = saved_errno;
    return failure;
}

static int restrict_filesystem(void)
{
    struct landlock_ruleset_attr rules = {0};
    int fd, saved_errno;
    long abi = syscall(SYS_landlock_create_ruleset, NULL, 0, LANDLOCK_CREATE_RULESET_VERSION);
    if (abi < 3) {
        if (abi >= 0)
            errno = ENOTSUP;
        return -1;
    }
    rules.handled_access_fs = LANDLOCK_ACCESS_FS_EXECUTE | LANDLOCK_ACCESS_FS_WRITE_FILE |
        LANDLOCK_ACCESS_FS_READ_FILE | LANDLOCK_ACCESS_FS_READ_DIR | LANDLOCK_ACCESS_FS_REMOVE_DIR |
        LANDLOCK_ACCESS_FS_REMOVE_FILE | LANDLOCK_ACCESS_FS_MAKE_CHAR | LANDLOCK_ACCESS_FS_MAKE_DIR |
        LANDLOCK_ACCESS_FS_MAKE_REG | LANDLOCK_ACCESS_FS_MAKE_SOCK | LANDLOCK_ACCESS_FS_MAKE_FIFO |
        LANDLOCK_ACCESS_FS_MAKE_BLOCK | LANDLOCK_ACCESS_FS_MAKE_SYM | LANDLOCK_ACCESS_FS_REFER |
        LANDLOCK_ACCESS_FS_TRUNCATE;
    /* No paths are granted. The sealed memfd lives on a kernel-internal
     * filesystem outside Landlock path handling. This is the only exec input. */
    fd = (int)syscall(SYS_landlock_create_ruleset, &rules, sizeof(rules.handled_access_fs), 0U);
    if (fd < 0)
        return -1;
    if (syscall(SYS_landlock_restrict_self, fd, 0U) < 0) {
        saved_errno = errno;
        close(fd);
        errno = saved_errno;
        return -1;
    }
    return close(fd);
}

#define LOAD_WORD(offset) BPF_STMT(BPF_LD | BPF_W | BPF_ABS, (offset))
#define CHECK_EQ(value, yes, no) BPF_JUMP(BPF_JMP | BPF_JEQ | BPF_K, (value), (yes), (no))
#define DECISION(value) BPF_STMT(BPF_RET | BPF_K, (value))
#define ALLOW DECISION(SECCOMP_RET_ALLOW)
#define KILL DECISION(SECCOMP_RET_KILL_PROCESS)
#define ARG_LOW(i) offsetof(struct seccomp_data, args[i])
#define ARG_HIGH(i) (ARG_LOW(i) + sizeof(uint32_t))

static int restrict_syscalls(void)
{
    struct sock_filter code[] = {
        LOAD_WORD(offsetof(struct seccomp_data, arch)),
        CHECK_EQ(AUDIT_ARCH_X86_64, 1, 0), KILL,
        /* Exact native syscall comparisons also reject the x32 syscall range. */
        LOAD_WORD(offsetof(struct seccomp_data, nr)),
        CHECK_EQ(SYS_exit, 0, 1), ALLOW,
        CHECK_EQ(SYS_exit_group, 0, 1), ALLOW,
        CHECK_EQ(SYS_write, 0, 6),
        LOAD_WORD(ARG_LOW(0)),
        CHECK_EQ(STDOUT_FILENO, 3, 0),
        CHECK_EQ(STDERR_FILENO, 2, 0),
        CHECK_EQ(ERROR_FD, 1, 0), /* Private setup reporting; closed on exec. */
        KILL, ALLOW,
        CHECK_EQ(SYS_execveat, 0, 9),
        LOAD_WORD(ARG_LOW(0)), CHECK_EQ(IMAGE_FD, 0, 7),
        LOAD_WORD(ARG_LOW(1)), CHECK_EQ((uint32_t)EMPTY_ADDRESS, 0, 5),
        LOAD_WORD(ARG_HIGH(1)), CHECK_EQ((uint32_t)(EMPTY_ADDRESS >> 32), 0, 3),
        LOAD_WORD(ARG_LOW(4)), CHECK_EQ(AT_EMPTY_PATH, 0, 1), ALLOW,
        KILL,
    };
    struct sock_fprog program = {(unsigned short)(sizeof(code) / sizeof(code[0])), code};
    return syscall(SYS_seccomp, SECCOMP_SET_MODE_FILTER, 0U, &program) == 0 ? 0 : -1;
}

enum setup_step {
    SETUP_PARENT, SETUP_SIGNALS, SETUP_FDS, SETUP_PRIVILEGES,
    SETUP_LANDLOCK, SETUP_LIMITS, SETUP_PAGE, SETUP_SECCOMP, SETUP_EXEC,
    SETUP_COUNT
};

static const char *const setup_steps[SETUP_COUNT] = {
    "watch supervisor", "reset child signals", "isolate child descriptors", "drop privileges",
    "restrict filesystem (requires Landlock ABI 3+)", "set resource limits",
    "reserve exec guard page", "install seccomp filter", "exec sealed ELF"
};

struct setup_error {
    int step;
    int error;
};

static __attribute__((noreturn)) void child_fail(int fd, enum setup_step step, int error)
{
    const struct setup_error info = {step, error};
    (void)write_all(fd, &info, sizeof(info));
    _exit(LAUNCHER_FAILED);
}

static int set_limit(int resource, rlim_t soft, rlim_t hard)
{
    struct rlimit old, bound;
    if (getrlimit(resource, &old) < 0)
        return -1;
    bound.rlim_cur = old.rlim_cur < soft ? old.rlim_cur : soft;
    bound.rlim_max = old.rlim_max < hard ? old.rlim_max : hard;
    return setrlimit(resource, &bound);
}

static int limit_core_files(void)
{
    struct rlimit old, bound;
    if (getrlimit(RLIMIT_CORE, &old) < 0)
        return -1;
    /* Linux pipe core helpers ignore zero, but skip dumps at value one.
     * One byte is also below Linux's minimum for an ELF core file. */
    bound.rlim_cur = bound.rlim_max = old.rlim_max == 0 ? 0 : 1;
    return setrlimit(RLIMIT_CORE, &bound);
}

static __attribute__((noreturn)) void run_child(pid_t parent, int image, int output, int errors, char *const args[])
{
    sigset_t none;
    struct __user_cap_header_struct header = {_LINUX_CAPABILITY_VERSION_3, 0};
    struct __user_cap_data_struct caps[2] = {{0}};
    char *const env[] = {NULL};
    void *const empty = (void *)(uintptr_t)EMPTY_ADDRESS;
    void *guard;
    int image_copy;

    if (prctl(PR_SET_PDEATHSIG, (unsigned long)SIGKILL, 0UL, 0UL, 0UL) < 0)
        child_fail(errors, SETUP_PARENT, errno);
    if (getppid() != parent)
        child_fail(errors, SETUP_PARENT, ESRCH);
    if (set_handler(SIGXCPU, SIG_DFL) < 0 || set_handler(SIGPIPE, SIG_DFL) < 0 ||
        set_handler(SIGINT, SIG_DFL) < 0 || set_handler(SIGTERM, SIG_DFL) < 0 ||
        set_handler(SIGHUP, SIG_DFL) < 0 || set_handler(SIGQUIT, SIG_DFL) < 0 ||
        sigemptyset(&none) < 0 || sigprocmask(SIG_SETMASK, &none, NULL) < 0)
        child_fail(errors, SETUP_SIGNALS, errno);

    image_copy = fcntl(image, F_DUPFD_CLOEXEC, ERROR_FD + 1);
    if (image_copy < 0 || dup3(output, STDOUT_FILENO, 0) < 0 ||
        dup3(output, STDERR_FILENO, 0) < 0 ||
        (errors != ERROR_FD && dup3(errors, ERROR_FD, O_CLOEXEC) < 0))
        child_fail(errors, SETUP_FDS, errno);
    if (dup3(image_copy, IMAGE_FD, O_CLOEXEC) < 0 || close(STDIN_FILENO) < 0 ||
        close_above(ERROR_FD + 1) < 0)
        child_fail(ERROR_FD, SETUP_FDS, errno);

    if (prctl(PR_SET_NO_NEW_PRIVS, 1UL, 0UL, 0UL, 0UL) < 0 ||
        prctl(PR_CAP_AMBIENT, (unsigned long)PR_CAP_AMBIENT_CLEAR_ALL, 0UL, 0UL, 0UL) < 0 ||
        syscall(SYS_capset, &header, caps) < 0)
        child_fail(ERROR_FD, SETUP_PRIVILEGES, errno);
    if (restrict_filesystem() < 0)
        child_fail(ERROR_FD, SETUP_LANDLOCK, errno);
    if (set_limit(RLIMIT_CPU, 1, 2) < 0 || limit_core_files() < 0 ||
        set_limit(RLIMIT_FSIZE, 0, 0) < 0 || set_limit(RLIMIT_NOFILE, 5, 5) < 0 ||
        set_limit(RLIMIT_AS, 128u * 1024u * 1024u, 128u * 1024u * 1024u) < 0 ||
        set_limit(RLIMIT_STACK, 8u * 1024u * 1024u, 8u * 1024u * 1024u) < 0)
        child_fail(ERROR_FD, SETUP_LIMITS, errno);
    guard = mmap(empty, PAGE_BYTES, PROT_READ, MAP_PRIVATE | MAP_ANONYMOUS | MAP_FIXED_NOREPLACE,
                 -1, 0);
    if (guard != empty)
        child_fail(ERROR_FD, SETUP_PAGE, guard == MAP_FAILED ? errno : ENOTSUP);
    if (restrict_syscalls() < 0)
        child_fail(ERROR_FD, SETUP_SECCOMP, errno);
    (void)syscall(SYS_execveat, IMAGE_FD, empty, args, env, AT_EMPTY_PATH);
    child_fail(ERROR_FD, SETUP_EXEC, errno);
}

static int64_t milliseconds(void)
{
    struct timespec now;
    if (clock_gettime(CLOCK_MONOTONIC, &now) < 0)
        return -1;
    return (int64_t)now.tv_sec * 1000 + now.tv_nsec / 1000000;
}

static int failure(const char *where, int error)
{
    fprintf(stderr, "RunSandbox: %s: %s\n", where, strerror(error));
    return LAUNCHER_FAILED;
}

/* Consume a bounded amount of output without depending on the rate of the
 * launcher's stdout consumer. The launcher relays it only after reaping. */
static int drain_output(int fd, unsigned char *bytes, size_t *size, int *eof)
{
    while (!*eof && *size <= OUTPUT_LIMIT) {
        ssize_t n = read(fd, bytes + *size, OUTPUT_LIMIT + 1u - *size);
        if (n > 0)
            *size += (size_t)n;
        else if (n == 0)
            *eof = 1;
        else if (errno == EAGAIN)
            break;
        else if (errno != EINTR)
            return -1;
    }
    return 0;
}

static int supervise(pid_t child, int output, int errors, int64_t deadline)
{
    unsigned char bytes[OUTPUT_LIMIT + 1u];
    size_t size = 0;
    struct setup_error info;
    int status, eof = 0, stop = 0, saved_errno = 0, reaped = 0;
    ssize_t data;
    for (;;) {
        struct pollfd event = {output, POLLIN, 0};
        int64_t now;
        pid_t waited = waitpid(child, &status, WNOHANG);
        if (waited < 0 && errno != EINTR) {
            saved_errno = errno;
            /* If the child is no longer ours, never signal a reusable PID. */
            reaped = errno == ECHILD;
            stop = LAUNCHER_FAILED;
            break;
        }
        reaped = waited == child;
        if (drain_output(output, bytes, &size, &eof) < 0) {
            saved_errno = errno;
            stop = LAUNCHER_FAILED;
        } else if (size > OUTPUT_LIMIT) {
            stop = OUTPUT_EXCEEDED;
        } else if (interrupted) {
            stop = LAUNCHER_FAILED;
        } else if (!reaped) {
            now = milliseconds();
            if (now < 0) {
                saved_errno = errno;
                stop = LAUNCHER_FAILED;
            } else if (now >= deadline) {
                stop = WALL_TIMEOUT;
            } else if (poll(&event, eof ? 0u : 1u, deadline - now < 10 ? (int)(deadline - now) : 10) < 0 &&
                       errno != EINTR) {
                saved_errno = errno;
                stop = LAUNCHER_FAILED;
            }
        }
        if (stop || reaped)
            break;
    }
    if (!reaped) {
        (void)kill(child, SIGKILL);
        while (waitpid(child, &status, 0) < 0 && errno == EINTR)
            ;
    }
    if (stop == LAUNCHER_FAILED) {
        if (saved_errno)
            return failure("supervise child", saved_errno);
        fprintf(stderr, "RunSandbox: interrupted by signal %d\n", (int)interrupted);
        return LAUNCHER_FAILED;
    }
    if (stop == WALL_TIMEOUT || stop == OUTPUT_EXCEEDED)
        fprintf(stderr, "RunSandbox: %s\n",
                stop == WALL_TIMEOUT ? "wall timeout" : "child output limit (64 KiB)");
    if (write_all(STDOUT_FILENO, bytes, size > OUTPUT_LIMIT ? OUTPUT_LIMIT : size) < 0)
        return failure("relay child output", errno);
    if (stop != 0)
        return stop;
    do {
        data = read(errors, &info, sizeof(info));
    } while (data < 0 && errno == EINTR);
    if (data == (ssize_t)sizeof(info) && info.step >= 0 && info.step < SETUP_COUNT)
        return failure(setup_steps[info.step], info.error);
    if (data != 0)
        return failure("read child setup status", data < 0 ? errno : EIO);
    if (WIFEXITED(status)) {
        int code = WEXITSTATUS(status);
        fprintf(stderr, "RunSandbox: child exit %d\n", code);
        return code >= WALL_TIMEOUT && code <= LAUNCHER_FAILED ? 1 : code;
    }
    if (WIFSIGNALED(status)) {
        int number = WTERMSIG(status);
        fprintf(stderr, "RunSandbox: child signal %d%s\n", number,
                number == SIGSYS ? " (SIGSYS: syscall policy)" :
                number == SIGXCPU ? " (SIGXCPU: CPU limit)" : "");
        return 1;
    }
    return failure("unexpected child status", EIO);
}

int main(int argc, char *argv[])
{
    int at = 1, timeout = 2000, image, pipe_output[2], pipe_errors[2], result;
    int flags;
    int64_t start;
    pid_t parent, child;
    const char *load_failure;
    sigset_t mask;
    if (argc == 2 && strcmp(argv[1], "--help") == 0) {
        usage(stdout);
        return 0;
    }
    if (at < argc && strcmp(argv[at], "--timeout-ms") == 0) {
        if (argc - at < 2 || (timeout = parse_timeout(argv[at + 1])) < 0) {
            usage(stderr);
            return LAUNCHER_FAILED;
        }
        at += 2;
    }
    if (at < argc && strcmp(argv[at], "--") == 0)
        ++at;
    else if (at < argc && argv[at][0] == '-')
        at = argc;
    if (at >= argc || !argv[at][0]) {
        usage(stderr);
        return LAUNCHER_FAILED;
    }
    if (getuid() != geteuid() || getgid() != getegid())
        return failure("set-ID launcher invocation is not supported", EPERM);
    if (close_above(3) < 0 || preserve_stdio_slots() < 0)
        return failure("prepare launcher descriptors (requires close_range)", errno);
    if (set_handler(SIGCHLD, SIG_DFL) < 0 || set_handler(SIGPIPE, SIG_IGN) < 0 ||
        set_handler(SIGINT, interruption) < 0 || set_handler(SIGTERM, interruption) < 0 ||
        set_handler(SIGHUP, interruption) < 0 || set_handler(SIGQUIT, interruption) < 0 ||
        sigemptyset(&mask) < 0 || sigprocmask(SIG_SETMASK, &mask, NULL) < 0)
        return failure("prepare launcher signals", errno);

    load_failure = load_image(argv[at], &image);
    if (load_failure)
        return failure(load_failure, errno);
    if (pipe2(pipe_output, O_CLOEXEC) < 0 || pipe2(pipe_errors, O_CLOEXEC) < 0 ||
        (flags = fcntl(pipe_output[0], F_GETFL)) < 0 ||
        fcntl(pipe_output[0], F_SETFL, flags | O_NONBLOCK) < 0)
        return failure("create private child pipes", errno);
    start = milliseconds();
    if (start < 0)
        return failure("read monotonic clock", errno);
    if (interrupted)
        return failure("interrupted before starting child", EINTR);
    parent = getpid();
    child = fork();
    if (child < 0)
        return failure("fork child", errno);
    if (child == 0)
        run_child(parent, image, pipe_output[1], pipe_errors[1], &argv[at]);
    close(image);
    close(pipe_output[1]);
    close(pipe_errors[1]);
    result = supervise(child, pipe_output[0], pipe_errors[0], start + timeout);
    close(pipe_output[0]);
    close(pipe_errors[0]);
    return result;
}

#else

int main(int argc, char *argv[])
{
    if (argc == 2 && strcmp(argv[1], "--help") == 0) {
        usage(stdout);
        return 0;
    }
    fputs("RunSandbox: unsupported host; Linux x86-64 (64-bit ABI) required\n", stderr);
    return LAUNCHER_FAILED;
}

#endif
